import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import { supabase } from "./supabaseClient";
import Dashboard from "./pages/Dashboard";
import Logs from "./pages/Logs";
import Analytics from "./pages/Analytics";
import AdminDashboard from "./pages/AdminDashboard";
import UserDashboard from "./pages/UserDashboard";
import LoginForm from "./components/LoginForm";

function App() {
  const [isAdmin, setIsAdmin] = useState(false);
  const [showLogin, setShowLogin] = useState(false); // toggle login form

  // Optional: persist login session
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      if (data.session) setIsAdmin(true);
    });
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setIsAdmin(false);
    setShowLogin(false);
  };

  const toggleLogin = () => setShowLogin((prev) => !prev);

  return (
    <Router>
      <nav
        style={{
          padding: "10px",
          borderBottom: "1px solid #ccc",
          display: "flex",
          justifyContent: "flex-end",
        }}
      >
        {isAdmin ? (
          <>
            <Link to="/dashboard" style={{ marginRight: "15px" }}>Dashboard</Link>
            <Link to="/logs" style={{ marginRight: "15px" }}>Logs</Link>
            <Link to="/analytics" style={{ marginRight: "15px" }}>Analytics</Link>
            <button onClick={handleLogout}>Logout</button>
          </>
        ) : (
          <button onClick={toggleLogin}>Admin Login</button>
        )}
      </nav>

      {/* Show login form only when button is clicked */}
      {!isAdmin && showLogin && <LoginForm setIsAdmin={setIsAdmin} setShowLogin={setShowLogin} />}

      <Routes>
        {isAdmin ? (
          <>
            <Route path="/dashboard" element={<Dashboard />} />
            <Route path="/logs" element={<Logs />} />
            <Route path="/analytics" element={<Analytics />} />
            <Route path="*" element={<AdminDashboard />} />
          </>
        ) : (
          <>
            {/* Show UserDashboard only if admin login form is not visible */}
            {!showLogin && <Route path="*" element={<UserDashboard />} />}
          </>
        )}
      </Routes>
    </Router>
  );
}

export default App;
